#include <stdio.h>

/* teste do desafio oi-na-tela — counter_protocol (03-tdd 3.9.3).
   A captura do stdout acontece DENTRO do teste: freopen para o arquivo
   temporario, chamada da funcao, leitura do arquivo de volta. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void tela(void);

SM_TEST(oi_na_tela) {
    freopen("sm_saida.tmp", "w", stdout);
    tela();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha impressa", linha, "oi\n",
              "a tela imprime oi");
    fclose(f);
}
